    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: caller (owner) and candidate newOwner.
    function testFuzz_property(address ownerCaller, address newOwner) public {
        // Keep inputs practical: ownerCaller must be non-zero so we can set it as initial owner via prank
        vm.assume(ownerCaller != address(0));
        // newOwner may be any address (including zero) to let fuzzer find mutant behavior

        // Initialize contract: call initialize to set up Ownable owner to address(this) via initializer
        // __Ownable_init sets owner to msg.sender inside initializer; call initialize via this test contract
        // But initialize is external and protected by initializer; call it from this test contract
        // Prepare dummy params for initialize (we pass zero for interface addresses since not used in this test)
        IERC20 dummy = IERC20(address(0));
        IRewardRouterV2 rr = IRewardRouterV2(address(0));
        IGlpManager gm = IGlpManager(address(0));
        c.initialize(dummy, dummy, rr, gm, address(0x1234), address(0x5678));

        // Now transfer ownership from current owner (this contract) to ownerCaller so ownerCaller becomes owner
        // Must be called by current owner (this contract)
        c.transferOwnership(ownerCaller);

        // Now act as ownerCaller to call transferOwnership(newOwner)
        bool ok;
        vm.prank(ownerCaller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule we assert: if the ownerCaller invoked transferOwnership and provided a non-zero newOwner,
        // then after the call owner() equals newOwner (i.e., the reference enforces that transfer to non-zero succeeds and sets owner).
        // This is a universal property the correct contract satisfies for ALL inputs; the mutant may violate it by allowing
        // a transfer to zero address (for inputs where newOwner==address(0)) to succeed and thus owner()==address(0) (but our assertion only requires
        // correctness when newOwner != address(0)). We therefore assert one statement that must hold for all inputs.

        if (newOwner == address(0)) {
            // If newOwner is zero we don't demand success; just check that if the call succeeded then owner() == address(0).
            // This branch keeps the test valid for all inputs and still allows fuzz to expose mutant when newOwner==address(0)
            if (ok) {
                assertTrue(c.owner() == address(0));
            } else {
                // call reverted as reference does — reference always reverts for this case, so ok==false for reference; assert holds trivially
                assertTrue(c.owner() == ownerCaller);
            }
        } else {
            // For non-zero newOwner the reference always allows transferOwnership by the owner and sets owner to newOwner.
            // So the call must succeed and owner() equals newOwner.
            assertTrue(ok && c.owner() == newOwner);
        }
    }
}

